def knapsack(capacity, items):
    from collections import defaultdict

    # Initialize memoization table with -1 to indicate unreachable states
    memo = [[-1 for _ in range(capacity + 1)] for _ in range(len(items) + 1)]

    def helper(i, j):
        if memo[i][j] != -1:
            return memo[i][j]

        if i == 0 or j == 0:
            return 0

        weight, value = items[i - 1]

        if weight > j:
            return helper(i - 1, j)

        max_val = max(
            helper(i - 1, j),
            value + helper(i - 1, j - weight)
        )
        memo[i][j] = max_val
        return max_val

    return helper(len(items), capacity)

